export type Cell = [number, number];

function keyOf([x, y]: Cell): string {
  return `${x},${y}`;
}

function neighborsOf([x, y]: Cell): Cell[] {
  const offsets = [-1, 0, 1];
  return offsets.flatMap((dx) =>
    offsets
      .filter((dy) => !(dx === 0 && dy === 0))
      .map((dy): Cell => [x + dx, y + dy]),
  );
}

function countLiveNeighbors(cell: Cell, liveKeys: Set<string>): number {
  return neighborsOf(cell).filter((neighbor) => liveKeys.has(keyOf(neighbor)))
    .length;
}

function survives(liveNeighborCount: number, isAlive: boolean): boolean {
  return isAlive
    ? liveNeighborCount === 2 || liveNeighborCount === 3
    : liveNeighborCount === 3;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const liveKeys = new Set(liveCells.map(keyOf));
  const candidates = new Map<string, Cell>(
    [...liveCells, ...liveCells.flatMap(neighborsOf)].map((cell) => [
      keyOf(cell),
      cell,
    ]),
  );
  return [...candidates].filter(([key, cell]) =>
    survives(countLiveNeighbors(cell, liveKeys), liveKeys.has(key)),
  ).map(([, cell]) => cell);
}

