function willBeAlive(isAlive: boolean, liveNeighborCount: number): boolean {
  return isAlive
    ? liveNeighborCount === 2 || liveNeighborCount === 3
    : liveNeighborCount === 3;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const liveKeys = new Set(liveCells.map(keyOf));
  const candidates = new Map<string, Cell>(
    [...liveCells, ...liveCells.flatMap(neighborsOf)].map((cell) => [
      keyOf(cell),
      cell,
    ]),
  );
  return [...candidates.values()].filter((cell) =>
    willBeAlive(liveKeys.has(keyOf(cell)), countLiveNeighbors(cell, liveKeys)),
  );
}
